-- =====================================================================
-- DATABASE: laptop_shop  |  MySQL 8.0+ / MariaDB 10.5+
-- Gồm: cấu trúc bảng + dữ liệu mẫu 100 laptop (đầy đủ thông tin chi tiết)
-- Cách chạy:  mysql -u root -p < laptop_shop.sql
-- Lưu ý: giá (VND) và thông số là DỮ LIỆU MẪU gần với thực tế để demo,
--        hãy đối chiếu lại nếu dùng cho bán hàng thật.
-- =====================================================================

DROP DATABASE IF EXISTS laptop_shop;
CREATE DATABASE laptop_shop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE laptop_shop;

-- ---------------------------------------------------------------------
-- 1. PHÂN QUYỀN & TÀI KHOẢN ADMIN
-- ---------------------------------------------------------------------
CREATE TABLE roles (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(50)  NOT NULL UNIQUE,
  description VARCHAR(255) NULL
) ENGINE=InnoDB;

CREATE TABLE users (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role_id        INT UNSIGNED NOT NULL,
  full_name      VARCHAR(100) NOT NULL,
  email          VARCHAR(150) NOT NULL UNIQUE,
  password_hash  VARCHAR(255) NOT NULL,
  phone          VARCHAR(20)  NULL,
  status         ENUM('active','locked') NOT NULL DEFAULT 'active',
  failed_logins  TINYINT UNSIGNED NOT NULL DEFAULT 0,
  locked_until   DATETIME NULL,
  last_login_at  DATETIME NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 2. HÃNG & DANH MỤC
-- ---------------------------------------------------------------------
CREATE TABLE brands (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL UNIQUE,
  slug        VARCHAR(120) NOT NULL UNIQUE,
  country     VARCHAR(80)  NULL,
  logo_url    VARCHAR(255) NULL,
  description TEXT NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  status      TINYINT(1) NOT NULL DEFAULT 1,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE categories (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  parent_id   INT UNSIGNED NULL,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(120) NOT NULL UNIQUE,
  description TEXT NULL,
  image_url   VARCHAR(255) NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  status      TINYINT(1) NOT NULL DEFAULT 1,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_cat_parent FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 3. SẢN PHẨM
-- ---------------------------------------------------------------------
CREATE TABLE products (
  id                  INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  sku                 VARCHAR(50)  NOT NULL UNIQUE,
  barcode             VARCHAR(50)  NULL UNIQUE,
  name                VARCHAR(255) NOT NULL,
  slug                VARCHAR(280) NOT NULL UNIQUE,
  brand_id            INT UNSIGNED NOT NULL,
  category_id         INT UNSIGNED NOT NULL,
  model_name          VARCHAR(100) NULL,
  condition_type      ENUM('new','like_new','used') NOT NULL DEFAULT 'new',
  condition_percent   TINYINT UNSIGNED NOT NULL DEFAULT 100,
  short_description   VARCHAR(500) NULL,
  description         TEXT NULL,
  -- giá
  cost_price          DECIMAL(15,0) NOT NULL DEFAULT 0,
  price               DECIMAL(15,0) NOT NULL,
  sale_price          DECIMAL(15,0) NULL,
  sale_start          DATETIME NULL,
  sale_end            DATETIME NULL,
  vat_rate            DECIMAL(4,2) NOT NULL DEFAULT 10.00,
  -- kho
  stock_quantity      INT NOT NULL DEFAULT 0,
  low_stock_threshold INT NOT NULL DEFAULT 5,
  allow_backorder     TINYINT(1) NOT NULL DEFAULT 0,
  warehouse_location  VARCHAR(50) NULL,
  -- bảo hành
  warranty_months     SMALLINT UNSIGNED NOT NULL DEFAULT 12,
  warranty_policy     VARCHAR(500) NULL,
  -- hiển thị
  status              ENUM('draft','active','hidden','discontinued') NOT NULL DEFAULT 'draft',
  is_featured         TINYINT(1) NOT NULL DEFAULT 0,
  is_new              TINYINT(1) NOT NULL DEFAULT 0,
  is_bestseller       TINYINT(1) NOT NULL DEFAULT 0,
  sort_order          INT NOT NULL DEFAULT 0,
  view_count          INT UNSIGNED NOT NULL DEFAULT 0,
  sold_count          INT UNSIGNED NOT NULL DEFAULT 0,
  -- SEO
  meta_title          VARCHAR(255) NULL,
  meta_description    VARCHAR(500) NULL,
  -- hệ thống
  version             INT UNSIGNED NOT NULL DEFAULT 1,
  created_by          INT UNSIGNED NULL,
  created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at          DATETIME NULL,
  CONSTRAINT fk_prod_brand FOREIGN KEY (brand_id)    REFERENCES brands(id),
  CONSTRAINT fk_prod_cat   FOREIGN KEY (category_id) REFERENCES categories(id),
  CONSTRAINT fk_prod_user  FOREIGN KEY (created_by)  REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT chk_price      CHECK (price > 0),
  CONSTRAINT chk_stock      CHECK (stock_quantity >= 0),
  CONSTRAINT chk_sale_price CHECK (sale_price IS NULL OR (sale_price > 0 AND sale_price < price)),
  INDEX idx_prod_name   (name),
  INDEX idx_prod_brand  (brand_id),
  INDEX idx_prod_cat    (category_id),
  INDEX idx_prod_status (status),
  INDEX idx_prod_price  (price),
  INDEX idx_prod_deleted(deleted_at)
) ENGINE=InnoDB;

CREATE TABLE product_specs (
  product_id         INT UNSIGNED PRIMARY KEY,
  -- CPU
  cpu_brand          VARCHAR(30)  NULL,
  cpu_model          VARCHAR(80)  NULL,
  cpu_cores          TINYINT UNSIGNED NULL,
  cpu_threads        TINYINT UNSIGNED NULL,
  -- RAM
  ram_gb             SMALLINT UNSIGNED NULL,
  ram_type           VARCHAR(30)  NULL,
  ram_max_gb         SMALLINT UNSIGNED NULL,
  -- Lưu trữ
  storage_gb         INT UNSIGNED NULL,
  storage_type       VARCHAR(50)  NULL,
  -- GPU
  gpu_type           ENUM('Onboard','Rời') NULL,
  gpu_model          VARCHAR(100) NULL,
  vram_gb            TINYINT UNSIGNED NULL,
  -- Màn hình
  screen_size_inch   DECIMAL(4,1) NULL,
  screen_resolution  VARCHAR(40)  NULL,
  screen_panel       VARCHAR(40)  NULL,
  refresh_rate_hz    SMALLINT UNSIGNED NULL,
  touchscreen        TINYINT(1) NOT NULL DEFAULT 0,
  -- Pin & sạc
  battery_wh         DECIMAL(5,1) NULL,
  charger_w          SMALLINT UNSIGNED NULL,
  -- Kết nối & khác
  wifi               VARCHAR(30)  NULL,
  bluetooth          VARCHAR(10)  NULL,
  ports              VARCHAR(300) NULL,
  os                 VARCHAR(50)  NULL,
  keyboard           VARCHAR(100) NULL,
  webcam             VARCHAR(50)  NULL,
  fingerprint        TINYINT(1) NOT NULL DEFAULT 0,
  weight_kg          DECIMAL(4,2) NULL,
  dimensions         VARCHAR(60)  NULL,
  color              VARCHAR(40)  NULL,
  material           VARCHAR(60)  NULL,
  CONSTRAINT fk_specs_prod FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  INDEX idx_spec_cpu (cpu_model),
  INDEX idx_spec_ram (ram_gb),
  INDEX idx_spec_storage (storage_gb)
) ENGINE=InnoDB;

CREATE TABLE product_images (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id  INT UNSIGNED NOT NULL,
  url         VARCHAR(255) NOT NULL,
  alt_text    VARCHAR(255) NULL,
  is_thumbnail TINYINT(1) NOT NULL DEFAULT 0,
  sort_order  INT NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_img_prod FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  INDEX idx_img_prod (product_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 4. KHO, LỊCH SỬ GIÁ, NHẬT KÝ
-- ---------------------------------------------------------------------
CREATE TABLE inventory_movements (
  id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id    INT UNSIGNED NOT NULL,
  type          ENUM('import','export','adjust','return') NOT NULL,
  quantity      INT NOT NULL,                 -- dương: nhập, âm: xuất
  stock_before  INT NOT NULL,
  stock_after   INT NOT NULL,
  unit_cost     DECIMAL(15,0) NULL,
  reason        VARCHAR(255) NULL,
  created_by    INT UNSIGNED NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_inv_prod FOREIGN KEY (product_id) REFERENCES products(id),
  CONSTRAINT fk_inv_user FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
  INDEX idx_inv_prod (product_id, created_at)
) ENGINE=InnoDB;

CREATE TABLE price_history (
  id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id  INT UNSIGNED NOT NULL,
  old_price   DECIMAL(15,0) NULL,
  new_price   DECIMAL(15,0) NOT NULL,
  old_sale    DECIMAL(15,0) NULL,
  new_sale    DECIMAL(15,0) NULL,
  changed_by  INT UNSIGNED NULL,
  changed_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ph_prod FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  INDEX idx_ph_prod (product_id, changed_at)
) ENGINE=InnoDB;

CREATE TABLE audit_logs (
  id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id     INT UNSIGNED NULL,
  action      VARCHAR(50)  NOT NULL,          -- create | update | delete | restore | login ...
  entity      VARCHAR(50)  NOT NULL,          -- product | brand | category ...
  entity_id   INT UNSIGNED NULL,
  old_values  JSON NULL,
  new_values  JSON NULL,
  ip_address  VARCHAR(45) NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_audit_entity (entity, entity_id),
  INDEX idx_audit_user (user_id, created_at)
) ENGINE=InnoDB;

