-- ---------------------------------------------------------------------
-- HÌNH ẢNH: mỗi sản phẩm 4 ảnh (ảnh 1 là ảnh đại diện)
-- Cần đặt file thật vào /uploads/products/<slug>-<n>.jpg hoặc cập nhật lại url
-- ---------------------------------------------------------------------
INSERT INTO product_images (product_id, url, alt_text, is_thumbnail, sort_order)
SELECT p.id,
       CONCAT('/uploads/products/', p.slug, '-', n.n, '.jpg'),
       CONCAT(p.name, ' - ảnh ', n.n),
       IF(n.n = 1, 1, 0),
       n.n
FROM products p
CROSS JOIN (SELECT 1 AS n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4) n;

-- ---------------------------------------------------------------------
-- KHO: ghi nhận nhập kho ban đầu & lịch sử giá ban đầu
-- ---------------------------------------------------------------------
INSERT INTO inventory_movements (product_id, type, quantity, stock_before, stock_after, unit_cost, reason, created_by)
SELECT id, 'import', stock_quantity + sold_count, 0, stock_quantity + sold_count, cost_price, 'Nhập kho ban đầu (dữ liệu mẫu)', 1 FROM products;

INSERT INTO inventory_movements (product_id, type, quantity, stock_before, stock_after, unit_cost, reason, created_by)
SELECT id, 'export', -sold_count, stock_quantity + sold_count, stock_quantity, cost_price, 'Đã bán (dữ liệu mẫu)', 1 FROM products WHERE sold_count > 0;

INSERT INTO price_history (product_id, old_price, new_price, old_sale, new_sale, changed_by)
SELECT id, NULL, price, NULL, sale_price, 1 FROM products;

-- ---------------------------------------------------------------------
-- VIEW: xem đầy đủ thông tin sản phẩm trong 1 truy vấn (dùng cho API)
-- ---------------------------------------------------------------------
CREATE VIEW v_product_full AS
SELECT
  p.id, p.sku, p.name, p.slug, b.name AS brand, c.name AS category,
  p.model_name, p.condition_type, p.short_description, p.description,
  p.cost_price, p.price, p.sale_price,
  COALESCE(p.sale_price, p.price) AS final_price,
  ROUND((p.price - p.cost_price) / p.price * 100, 1) AS margin_percent,
  p.stock_quantity,
  CASE WHEN p.stock_quantity = 0 THEN 'Hết hàng'
       WHEN p.stock_quantity <= p.low_stock_threshold THEN 'Sắp hết'
       ELSE 'Còn hàng' END AS stock_status,
  p.warranty_months, p.status, p.is_featured, p.is_new, p.is_bestseller,
  p.view_count, p.sold_count,
  s.cpu_brand, s.cpu_model, s.cpu_cores, s.cpu_threads,
  s.ram_gb, s.ram_type, s.ram_max_gb, s.storage_gb, s.storage_type,
  s.gpu_type, s.gpu_model, s.vram_gb,
  s.screen_size_inch, s.screen_resolution, s.screen_panel, s.refresh_rate_hz, s.touchscreen,
  s.battery_wh, s.charger_w, s.wifi, s.bluetooth, s.ports, s.os, s.keyboard, s.webcam,
  s.fingerprint, s.weight_kg, s.dimensions, s.color, s.material,
  (SELECT url FROM product_images i WHERE i.product_id = p.id AND i.is_thumbnail = 1 LIMIT 1) AS thumbnail,
  p.created_at, p.updated_at
FROM products p
JOIN brands b      ON b.id = p.brand_id
JOIN categories c  ON c.id = p.category_id
LEFT JOIN product_specs s ON s.product_id = p.id
WHERE p.deleted_at IS NULL;

